(function(){
var M="M5",BLOCOS=[[15,"Plano","Lê o guia, escolhe por onde começas, escreve as três coisas que vais fazer."],[55,"Fazer","Trabalho a sério. Se encravares, regra dos três antes de mim."],[20,"Rever e entregar","Lista da rubrica, regra do original, autoavaliação, copiar para o Teams."]],T=[{"n":1,"extra":false,"titulo":"Resposta à carta de Teresa","quem":"individual","grupo":false,"passos":["Relê a carta de Teresa e anota o que ela sabe, o que ele sabe e o que nenhum dos dois sabe ainda.","Escreve com a voz de Simão (o orgulho, a pressa, a paixão), sem copiar frases do livro.","Mantém a situação: onde ele está, o que o espera, o que já não pode mudar.","Conta as palavras, põe o lugar e a data e assina."],"entrega":"A carta.","alternativa":"","encomenda":"Responde à última carta de Teresa como Simão, sem desfazer o que o romance já decidiu.","produto":"Uma carta de 220 a 280 palavras, datada e assinada por Simão. Ficheiro: M5_Tarefa1_Carta.docx (ou PDF).","criterios":["A carta respeita o que o romance já decidiu: situação, tempo, o que cada um sabe.","Lê-se a voz de Simão, sem frases copiadas do livro.","220 a 280 palavras, datada e assinada, sem erros."],"exemplo":{"titulo":"Início da carta","texto":"Teresa: lida a tua carta três vezes, e à terceira já não lia, dizia-a de cor. Dizes que te vais apagando como uma luz a que falta o azeite; eu digo-te que a luz não é tua, é minha, e que se apaga a que me resta por não te ver. Sabes onde estou e sabes o que me espera: não me peças que fuja, porque já não há para onde. O que te peço é pouco e é tudo: que não me esqueças antes de eu partir.","nota":"Voz de Simão, situação respeitada, nada do que vem depois é adiantado, frases próprias."},"fraco":{"texto":"Olá Teresa, recebi a tua carta. Estou bem, espero que tu também. Não te preocupes, vai tudo correr bem e vamos ficar juntos. Beijinhos, Simão.","porque":"Não é a voz de Simão, ignora a situação do romance e promete o que o livro nega."},"rubrica":[{"nome":"Resposta e coerência com a obra","niveis":["responde a duas perguntas de Teresa; nada contradiz o romance; uma memória do que os dois viveram","responde a uma pergunta, ou um pormenor contradiz a obra","fala de amor em geral, sem responder","não se reconhece a carta de Teresa"],"pontos":[54,38,22,5]},{"nome":"Marcas da carta e voz","niveis":["local, data, vocativo, despedida, assinatura; a voz é a de Simão do princípio ao fim","falta uma marca, ou a voz oscila uma vez","faltam duas marcas, ou a voz é a do aluno","não é uma carta"],"pontos":[53,37,21,5]},{"nome":"Língua e número de palavras","niveis":["dois recursos expressivos com efeito; português atual com ecos do texto; 220 a 300 palavras; correta","pequenos erros; limite cumprido","erros frequentes, ou limite falhado","erros que impedem a leitura"],"pontos":[53,37,21,5]},{"nome":"Respostas das unidades (percurso)","niveis":["todas as respostas das unidades enviadas no prazo, com 80 a 120 palavras, citação do texto e leitura própria","a maior parte das respostas completas, ou todas com um movimento em falta","uma resposta completa","sem respostas"],"pontos":[40,28,16,4]}]},{"n":2,"extra":false,"titulo":"«Falhámos a vida?»","quem":"individual","grupo":false,"passos":["Escolhe a decisão de hoje (o curso, a cidade, o primeiro emprego, ficar ou sair) e escreve a tese numa frase: falha-se ou não, e porquê.","Dá o primeiro argumento com uma citação curta do último capítulo e o segundo com um exemplo de hoje, sem nomes reais.","Reconhece a objeção mais forte e responde-lhe.","Conclui voltando à tese, com outra formulação."],"entrega":"O texto de opinião.","alternativa":"","encomenda":"Pega na frase de Ega a Carlos, no fim de Os Maias, e discute se ela se aplica a uma decisão que alguém da tua idade toma hoje.","produto":"Um texto de opinião de 250 a 300 palavras, com título, tese na primeira frase, dois argumentos (um com citação do romance, outro de hoje), objeção respondida e conclusão. Ficheiro: M5_Tarefa2_Opiniao.docx (ou PDF).","criterios":["A tese está na primeira frase e é discutível.","Um argumento cita o romance, o outro vem de hoje; a objeção é respondida.","250 a 300 palavras, conectores variados, sem erros."],"exemplo":{"titulo":"«Falha-se a vida aos dezassete?» (início)","texto":"Defendo que não se falha a vida aos dezassete anos: adia-se. Ega diz a Carlos que falharam a vida, e Carlos responde que talvez; mas a frase é dita por dois homens que tiveram tudo e não fizeram nada, não por quem ainda não começou. Primeiro argumento: no romance, o que falha não é a escolha, é a falta dela; Carlos nunca decide, deixa decidir. Segundo: quem escolhe hoje um curso que não é o dos pais não falha, mesmo que mude; falhar é ficar à espera, como no Ramalhete. Dir-me-ão que há escolhas que fecham portas; respondo que a porta fechada ainda é uma escolha, e a de Carlos nunca foi.","nota":"Tese discutível, argumento com o romance, argumento de hoje, objeção respondida, voz própria."},"fraco":{"texto":"Eu acho que a vida é o que fazemos dela. Os Maias é um livro muito grande sobre uma família. Cada um tem a sua opinião.","porque":"Não há tese discutível, não cita o romance, não há argumentos nem objeção."},"rubrica":[{"nome":"Tese e argumentos","niveis":["tese discutível na primeira frase; dois argumentos, um com exemplo do excerto e outro de hoje","tese clara; um argumento sem exemplo","tese vaga, ou exemplos que não a provam","sem tese"],"pontos":[67,47,27,7]},{"nome":"Contra-argumento e conclusão","niveis":["reconhece a objeção mais forte e responde-lhe; a conclusão volta à tese","objeção fraca, ou conclusão que repete","sem contra-argumento","sem conclusão"],"pontos":[67,47,27,7]},{"nome":"Língua e número de palavras","niveis":["conectores variados, modalização, citação curta integrada; 200 a 300 palavras; correto","pequenos erros; limite cumprido","erros frequentes, ou limite falhado","erros que impedem a leitura"],"pontos":[66,46,26,7]}]},{"n":3,"extra":false,"titulo":"Crónica da visita ao Porto","quem":"individual","grupo":false,"passos":["Na visita, escolhe um lugar e toma notas: um pormenor, gente em ação, uma fala.","Encontra a ligação a Camilo ou a Simão (a cadeia da Relação, a rua, o rio) e confirma-a numa fonte.","Escreve a crónica do momento: o pormenor, a gente, a fala, e a ligação, sem a explicar demais.","Conta as palavras, assina e lista as fontes."],"entrega":"A crónica e a lista das fontes.","alternativa":"Se faltaste à visita, escolhe um lugar de Lisboa ligado a um escritor e faz o mesmo trabalho com os mesmos critérios.","encomenda":"Escreve a crónica de um momento vivido num lugar da visita ao Porto e liga esse lugar a Camilo ou a Simão.","produto":"Um texto de 200 a 250 palavras, com título, assinatura e lista das fontes. Ficheiro: M5_Tarefa3_Cronica.docx (ou PDF).","criterios":["Há um lugar, um pormenor, gente em ação e uma fala.","A ligação a Camilo ou a Simão é concreta e confirmada numa fonte.","200 a 250 palavras, com assinatura, sem erros."],"exemplo":{"titulo":"«A janela da Relação» (início)","texto":"A janela é pequena e está alta; de baixo, na rua, não se vê quem lá está. Um guia dizia que Camilo escreveu o livro em quinze dias atrás de uma destas, e um grupo de turistas tirou fotografias à parede. Uma mulher que passava com um saco disse, sem parar: «Quinze dias? Eu levo mais a escrever um recado.» Pensei em Simão a olhar para fora, e em como o romance é todo feito de gente a olhar de janelas para quem não pode entrar.","nota":"Lugar, pormenor, gente, fala; ligação a Camilo e a Simão, confirmada; sem explicar demais."},"fraco":{"texto":"A visita ao Porto foi muito boa. Vimos a casa de Camilo e a cadeia. O Porto é uma cidade muito bonita e com muita história.","porque":"Não há momento, pormenor, fala nem ligação concreta; são adjetivos."},"rubrica":[{"nome":"Lugar e método","niveis":["um lugar da visita visto de perto: pormenor, gente em ação, uma fala; liga-se a Camilo ou a Simão","lugar claro; ligação a Camilo fraca","conta sem 