if(window.EPIJogo)EPIJogo.montar({casca:CASCA,el:$("#baralho"),marca:"M3",depois:"<article class=\"c\" data-ativ=\"1\"><p class=\"rot\">Cartão extra: ler a fundo</p><p class=\"tit\">Do «som alto» ao «Nô mais»</p><p class=\"sub\">_Os Lusíadas_: o princípio e o fim</p><div class=\"acoes\"><button type=\"button\" data-abrir=\"1\" data-url=\"https://pedrohfernandes-klk.github.io/pt/m3/camoes-invocacoes/\" data-titulo=\"Do «som alto» ao «Nô mais»\">Fazer agora</button><span class=\"estado\" data-ativ-estado></span><a href=\"https://pedrohfernandes-klk.github.io/pt/m3/camoes-invocacoes/\">Abrir numa página só</a></div></article><article class=\"c\"><p class=\"rot\">A tarefa</p><p>O enunciado e a grelha /20 estão na <a href=\"https://pedrohfernandes-klk.github.io/pt/tarefas/m3-u2/\">Aula de tarefa</a>.</p></article><div class=\"prox\"><a href=\"https://pedrohfernandes-klk.github.io/pt/m3/licao-m3-f11/\">← Lição anterior</a><a href=\"https://pedrohfernandes-klk.github.io/pt/m3/licao-m3-f16/\">Lição seguinte →</a></div><nav class=\"portas-ext\" aria-label=\"Opcional: para ir mais longe\"><p class=\"pe-rot\">Opcional</p><a class=\"pe-l\" href=\"https://pedrohfernandes-klk.github.io/pt/atlas/#figura-sophia-andresen\" data-fig=\"sophia-andresen\"><span class=\"pe-t\">Atlas: Sophia de Mello Breyner Andresen</span><span class=\"estado\" data-atlas-estado></span><span class=\"pe-s\" aria-hidden=\"true\">→</span></a></nav>",aoDepois:function(){atlasEstado();pintar()},itens:CARTOES,chave:K,titulo:"Lição M3-F10",emblema:"data:image/jpeg;base64,",simbolo:"<svg class=\"simbolo\" viewBox=\"0 0 48 48\" aria-hidden=\"true\" data-ico=\"pena\" data-gesto=\"escreve\"><path d=\"M38 8c-12 2-22 10-26 24\"/><path d=\"M38 8c-2 12-8 22-20 26\"/><path d=\"M12 32l-4 8\"/><path d=\"M18 24l10-2M14 30l8-3\"/></svg>",louro:"<svg class=\"simbolo\" viewBox=\"0 0 48 48\" aria-hidden=\"true\" data-ico=\"louro\"><path d=\"M24 44c-11-6-16-18-14-32\"/><path d=\"M24 44c11-6 16-18 14-32\"/><path d=\"M11 18c3-1 6 1 6 5-3 1-6-1-6-5zM10 27c3 0 6 2 6 6-3 0-6-2-6-6zM13 35c3 0 6 2 5 6-3 0-6-2-5-6zM37 18c-3-1-6 1-6 5 3 1 6-1 6-5zM38 27c-3 0-6 2-6 6 3 0 6-2 6-6zM35 35c-3 0-6 2-5 6 3 0 6-2 5-6z\"/></svg>",pistas:["Em I, 4 e 5 o Poeta invoca as Tágides, ninfas do Tejo, e pede «um som alto e sublimado» e a «tuba canora e belicosa»: um poema épico.","Em X, 145 diz «Nô mais, Musa, nô mais»: a Lira está «destemperada», a voz «enrouquecida», não do canto, mas de cantar «a gente surda e endurecida».","O ensaio extra sem nota parte de uma pergunta sobre a Musa, defende uma tese com citações por canto e estância e assenta em três fontes fiáveis."],gestalt:true,percurso:"https://pedrohfernandes-klk.github.io/pt/m3/#m3-f10",seguinte:"https://pedrohfernandes-klk.github.io/pt/m3/licao-m3-f16/",fim:function(s){gravar(K+"-a1",{lida:true,t:Date.now()});pintar();(function(){var ff=$("#baralho .cartao.fim .frase-fim");if(ff){var q=document.createElement("p");q.className="frase-fim";q.setAttribute("role","status");q.textContent="Lição feita: o percurso já a marca.";ff.parentNode.insertBefore(q,ff)}else avisar("Lição feita: o percurso já a marca")})()}});
